function decorateTool(button,id,key){button.replaceChildren();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 32 32');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',toolPaths[id]);path.setAttribute('fill','none');path.setAttribute('stroke','currentColor');path.setAttribute('stroke-width','1.4');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');svg.append(path);const label=document.createElement('span');label.className='tool-label';label.textContent=toolNames[id];const k=document.createElement('kbd');k.textContent=key;button.append(svg,label,k);button.setAttribute('aria-label',toolNames[id]+'，快捷键'+key);}
