 if(gesture?.kind==='lift'){const g=gesture,recovery=g.lastY-g.minY,raised=g.height>=18&&recovery>=Math.max(18,g.height*.45),downOnly=g.height<18&&g.lastY-g.anchorY>=24,valid=raised||downOnly,power=clamp((raised?g.height:g.lastY-g.anchorY)/110,.22,1);$('gesture-fill').style.width=(valid?power*100:Math.min(100,Math.max(g.height,g.maxDown)/110*100))+'%';$('gesture-label').textContent=valid?'松手落锤 · 力度'+Math.round(power*100)+'%':g.height>=18?'已提起 · 下划回落':'向下划 ≥24px';$('gesture-meter').dataset.ready=String(valid);}
